import { FormikProps, FormikValues, useFormikContext } from 'formik';
import ToolOptionGroups, { ToolOptionGroup } from './ToolOptionGroups';
import { useTranslation } from 'react-i18next';

export type UpdateField<T> = <Y extends keyof T>(field: Y, value: T[Y]) => void;
type NonEmptyArray<T> = [T, ...T[]];
export type GetGroupsType<T> = (
  formikProps: FormikProps<T> & { updateField: UpdateField<T> }
) => NonEmptyArray<ToolOptionGroup>;

export default function ToolOptions<T extends FormikValues>({
  children,
  getGroups,
  vertical
}: {
  children?: ReactNode;
  getGroups: GetGroupsType<T> | null;
  vertical?: boolean;
}) {
  const { t } = useTranslation();
  const theme = useTheme();
  const formikContext = useFormikContext<T>();

  // Early return if no groups to display
  if (!getGroups) {
    return null;
  }

  const updateField: UpdateField<T> = (field, value) => {
    formikContext.setFieldValue(field as string, value);
  };

  return (
    <Box
      sx={{
        mb: 2,
        borderRadius: 2,
        padding: 2,
        backgroundColor: 'background.lightSecondary',
        boxShadow: '2'
      }}
      mt={2}
    >
      <Stack direction={'row'} spacing={1} alignItems={'center'}>
        <SettingsIcon />
        <Typography fontSize={22}>{t('toolOptions.title')}</Typography>
      </Stack>
      <Box mt={2}>
        <Stack direction={'row'} spacing={2}>
          <ToolOptionGroups
            groups={getGroups({ ...formikContext, updateField }) ?? null}
            vertical={vertical}
          />
          {children}
        </Stack>
      </Box>
    </Box>
  );
}

import {
  Box,
  CircularProgress,
  Typography,
  useTheme,
  Button
} from '@mui/material';
import InputHeader from '../InputHeader';
import greyPattern from '@assets/grey-pattern.png';
import { globalInputHeight } from '../../config/uiConfig';
import ResultFooter from './ResultFooter';
import { useTranslation } from 'react-i18next';
import React, { useContext } from 'react';
import { CustomSnackBarContext } from '../../contexts/CustomSnackBarContext';

export default function ToolMultiFileResult({
  title = 'Result',
  value,
  zipFile,
  loading,
  loadingText
}: {
  title?: string;
  value: File[];
  zipFile?: File | null;
  loading?: boolean;
  loadingText?: string;
}) {
  const { t } = useTranslation();
  const theme = useTheme();
  const { showSnackBar } = useContext(CustomSnackBarContext);

  const getFileType = (
    file: File
  ): 'image' | 'video' | 'audio' | 'pdf' | 'unknown' => {
    if (file.type.startsWith('image/')) return 'image';
    if (file.type.startsWith('video/')) return 'video';
    if (file.type.startsWith('audio/')) return 'audio';
    if (file.type.startsWith('application/pdf')) return 'pdf';
    return 'unknown';
  };

  const handleDownload = (file: File) => {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url;
    a.download = file.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleCopy = () => {
    if (zipFile) {
      const blob = new Blob([zipFile], { type: zipFile.type });
      const clipboardItem = new ClipboardItem({ [zipFile.type]: blob });
      navigator.clipboard
        .write([clipboardItem])
        .then(() => showSnackBar(t('toolMultiFileResult.copied'), 'success'))
        .catch((err) => {
          showSnackBar(
            t('toolMultiFileResult.copyFailed', { error: err }),
            'error'
          );
        });
    }
  };

  return (
    <Box>
      <InputHeader title={title || t('toolMultiFileResult.result')} />
      <Box
        sx={{
          width: '100%',
          height: globalInputHeight,
          overflowY: 'auto',
          display: 'flex',
          flexDirection: 'column',
          gap: 2,
          border: 1,
          borderRadius: 2,
          boxShadow: '5',
          bgcolor: 'background.paper',
          alignItems: 'center',
          p: 2
        }}
      >
        {loading ? (
          <Box
            sx={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              height: globalInputHeight
            }}
          >
            <CircularProgress />
            <Typography variant="body2" sx={{ mt: 2 }}>
              {loadingText || t('toolMultiFileResult.loading')}
            </Typography>
          </Box>
        ) : (
          value.length > 0 &&
          value.map((file, idx) => {
            const preview = URL.createObjectURL(file);
            const fileType = getFileType(file);

            return (
              <Box
                key={idx}
                sx={{
                  backgroundImage:
                    fileType === 'image' && theme.palette.mode !== 'dark'
                      ? `url(${greyPattern})`
                      : 'none',
                  p: 1,
                  border: '1px solid #ddd',
                  borderRadius: 2,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center'
                }}
              >
                {fileType === 'image' && (
                  <img
                    src={preview}
                    alt={`Preview ${idx}`}
                    style={{ maxWidth: '100%', maxHeight: 300 }}
                  />
                )}
                {fileType === 'video' && (
                  <video src={preview} controls style={{ maxWidth: '100%' }} />
                )}
                {fileType === 'audio' && (
                  <audio src={preview} controls style={{ width: '100%' }} />
                )}
                {fileType === 'pdf' && (
                  <iframe src={preview} width="100%" height="400px" />
                )}
                {fileType === 'unknown' && (
                  <Typography>File ready. Click below to download.</Typography>
                )}
                <Button
                  onClick={() => handleDownload(file)}
                  size="small"
                  sx={{ mt: 1 }}
                  variant="contained"
                >
                  Download {file.name}
                </Button>
              </Box>
            );
          })
        )}
      </Box>
      <ResultFooter
        downloadLabel={'Download All as ZIP'}
        hideCopy
        disabled={!zipFile}
        handleDownload={() => zipFile && handleDownload(zipFile)}
      />
    </Box>
  );
}

import { useCallback, useEffect, useRef } from 'react';
import _ from 'lodash';

/**
 * Debounce hook.
 * @param {T} callback
 * @param {number} delay
 * @returns {T}
 */
function useDebounce<T extends (...args: never[]) => void>(
  callback: T,
  delay: number
): T {
  const callbackRef = useRef<T>(callback);

  // Update the current callback each time it changes.
  useEffect(() => {
    callbackRef.current = callback;
  }, [callback]);

  const debouncedFn = useCallback(
    _.debounce((...args: never[]) => {
      callbackRef.current(...args);
    }, delay),
    [delay]
  );

  useEffect(() => {
    // Cleanup function to cancel any pending debounced calls
    return () => {
      debouncedFn.cancel();
    };
  }, [debouncedFn]);

  return debouncedFn as unknown as T;
}

export default useDebounce;

import { DependencyList, EffectCallback, useEffect, useRef } from 'react';

/**
 * The useUpdateEffect function is a custom hook that behaves like useEffect, but only runs on updates and not on initial mount.
 * It takes in an effect function and an optional dependency list as parameters.
 * It returns nothing.
 */
const useUpdateEffect = (effect: EffectCallback, deps?: DependencyList) => {
  const isInitialMount = useRef(true);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
    }
    return effect();
  }, deps);
};

export default useUpdateEffect;

