import { Box } from '@mui/material';
import React, { useState } from 'react';
import * as Yup from 'yup';
import ToolImageInput from '@components/input/ToolImageInput';
import ToolFileResult from '@components/result/ToolFileResult';
import ColorSelector from '@components/options/ColorSelector';
import Color from 'color';
import TextFieldWithDesc from 'components/options/TextFieldWithDesc';
import { areColorsSimilar } from 'utils/color';
import ToolContent from '@components/ToolContent';
import { ToolComponentProps } from '@tools/defineTool';
import { GetGroupsType } from '@components/options/ToolOptions';

const initialValues = {
  fromColor: 'white',
  similarity: '10',
  backgroundColor: '#ffffff' // NEW
};

const validationSchema = Yup.object({
  // splitSeparator: Yup.string().required('The separator is required')
});

export default function CreateTransparent({ title }: ToolComponentProps) {
  const [input, setInput] = useState<File | null>(null);
  const [result, setResult] = useState<File | null>(null);

  const compute = (optionsValues: typeof initialValues, input: any) => {
    if (!input) return;
    const { fromColor, similarity, backgroundColor } = optionsValues;

    let fromRgb: [number, number, number];
    let bgRgb: [number, number, number];

    try {
      //@ts-ignore
      fromRgb = Color(fromColor).rgb().array();
      //@ts-ignore
      bgRgb = Color(backgroundColor).rgb().array();
    } catch (err) {
      return;
    }
    const processImage = async (
      file: File,
      fromColor: [number, number, number],
      similarity: number
    ) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (ctx == null) return;
      const img = new Image();

      img.src = URL.createObjectURL(file);
      await img.decode();

      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);

      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data: Uint8ClampedArray = imageData.data;

      for (let i = 0; i < data.length; i += 4) {
        const currentColor: [number, number, number] = [
          data[i],
          data[i + 1],
          data[i + 2]
        ];
        if (areColorsSimilar(currentColor, fromColor, similarity)) {
          // data[i + 3] = 0; // Set alpha to 0 (transparent)
          // NEW LOGIC: replace with background color
          data[i] = bgRgb[0];
          data[i + 1] = bgRgb[1];
          data[i + 2] = bgRgb[2];
          data[i + 3] = 255;
        }
      }

      ctx.putImageData(imageData, 0, 0);

      canvas.toBlob((blob) => {
        if (blob) {
          const newFile = new File([blob], file.name, { type: 'image/png' });
          setResult(newFile);
        }
      }, 'image/png');
    };

    processImage(input, fromRgb, Number(similarity));
  };

  const getGroups: GetGroupsType<typeof initialValues> = ({
    values,
    updateField
  }) => [
    {
      title: 'From color and similarity',
      component: (
        <Box>
          <ColorSelector
            value={values.fromColor}
            onColorChange={(val) => updateField('fromColor', val)}
            description={'Replace this color (from color)'}
            inputProps={{ 'data-testid': 'color-input' }}
          />
          <TextFieldWithDesc
            value={values.similarity}
            onOwnChange={(val) => updateField('similarity', val)}
            description={
              'Match this % of similar colors of the from color. For example, 10% white will match white and a little bit of gray.'
            }
          />

          {/* NEW FEATURE */}
          <ColorSelector
            value={values.backgroundColor}
            onColorChange={(val) => updateField('backgroundColor', val)}
            description={'Background color for replaced pixels'}
          />
        </Box>
      )
    }
  ];

  return (
    <ToolContent
      title={title}
      inputComponent={
        <ToolImageInput
          value={input}
          onChange={setInput}
          accept={['image/*']}
          title={'Input image'}
        />
      }
      resultComponent={
        <ToolFileResult
          title={'Transparent PNG'}
          value={result}
          extension={'png'}
        />
      }
      initialValues={initialValues}
      getGroups={getGroups}
      compute={compute}
      input={input}
      validationSchema={validationSchema}
      toolInfo={{
        title: 'Create Transparent PNG',
        description:
          'This tool allows you to make specific colors in an image transparent. You can select the color to replace and adjust the similarity threshold to include similar colors.'
      }}
    />
  );
}

import React, { useCallback, useState } from 'react';
import { Box } from '@mui/material';
import ToolImageInput from '@components/input/ToolImageInput';
import ToolContent from '@components/ToolContent';
import { ToolComponentProps } from '@tools/defineTool';

// Import the image editor with proper typing
import FilerobotImageEditor, {
  FilerobotImageEditorConfig
} from 'react-filerobot-image-editor';

export default function ImageEditor({ title }: ToolComponentProps) {
  const [input, setInput] = useState<File | null>(null);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [imageUrl, setImageUrl] = useState<string | null>(null);

  // Handle file input change
  const handleInputChange = useCallback((file: File | null) => {
    setInput(file);
    if (file) {
      // Create object URL for the image editor
      const url = URL.createObjectURL(file);
      setImageUrl(url);
      setIsEditorOpen(true);
    } else {
      setImageUrl(null);
    }
  }, []);

  const onCloseEditor = (reason: string) => {
    setIsEditorOpen(false);
    setImageUrl(null);
  };

  // Handle save from image editor
  const handleSave: FilerobotImageEditorConfig['onSave'] = (
    editedImageObject,
    designState
  ) => {
    if (editedImageObject && editedImageObject.imageBase64) {
      // Convert base64 to blob
      const base64Data = editedImageObject.imageBase64.split(',')[1];
      const byteCharacters = atob(base64Data);
      const byteNumbers = new Array(byteCharacters.length);

      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }

      const byteArray = new Uint8Array(byteNumbers);
      const blob = new Blob([byteArray], { type: editedImageObject.mimeType });

      const editedFile = new File(
        [blob],
        editedImageObject.fullName ?? 'edited.png',
        {
          type: editedImageObject.mimeType
        }
      );
      // Create a temporary download link
      const url = URL.createObjectURL(editedFile);
      const a = document.createElement('a');
      a.href = url;
      a.download = editedFile.name; // This will be the name of the downloaded file
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);

      // Release the blob URL
      URL.revokeObjectURL(url);
    }
  };

  const getDefaultImageName = () => {
    if (!input) return;
    const originalName = input?.name || 'edited-image';
    const nameWithoutExt = originalName.replace(/\.[^/.]+$/, '');
    const editedFileName = `${nameWithoutExt}-edited`;
    return editedFileName;
  };

  return (
    <ToolContent
      title={title}
      initialValues={{}}
      getGroups={null}
      input={input}
      inputComponent={
        isEditorOpen ? (
          imageUrl && (
            <Box style={{ width: '100%', height: '70vh' }}>
              <FilerobotImageEditor
                source={imageUrl}
                onSave={handleSave}
                onClose={onCloseEditor}
                annotationsCommon={{
                  fill: 'blue'
                }}
                defaultSavedImageName={getDefaultImageName()}
                Rotate={{ angle: 90, componentType: 'slider' }}
                savingPixelRatio={1}
                previewPixelRatio={1}
              />
            </Box>
          )
        ) : (
          <ToolImageInput
            value={input}
            onChange={handleInputChange}
            accept={['image/*']}
            title="Upload Image to Edit"
          />
        )
      }
      toolInfo={{
        title: 'Image Editor',
        description:
          'A powerful image editing tool that provides professional-grade features including cropping, rotating, color adjustments, text annotations, drawing tools, and watermarking. Edit your images directly in your browser without the need for external software.'
      }}
      compute={() => {}}
    />
  );
}

import { Box } from '@mui/material';
import React, { useContext, useState } from 'react';
import * as Yup from 'yup';
import ToolImageInput from '@components/input/ToolImageInput';
import ToolTextResult from '@components/result/ToolTextResult';
import { GetGroupsType } from '@components/options/ToolOptions';
import ToolContent from '@components/ToolContent';
import { ToolComponentProps } from '@tools/defineTool';
import SelectWithDesc from '@components/options/SelectWithDesc';
import CheckboxWithDesc from '@components/options/CheckboxWithDesc';
import CircularProgress from '@mui/material/CircularProgress';
import { extractTextFromImage, getAvailableLanguages } from './service';
import { InitialValuesType } from './types';
import { CustomSnackBarContext } from '../../../../../contexts/CustomSnackBarContext';

const initialValues: InitialValuesType = {
  language: 'eng',
  detectParagraphs: true
};

const validationSchema = Yup.object({
  language: Yup.string().required('Language is required')
});

export default function ImageToText({ title }: ToolComponentProps) {
  const [input, setInput] = useState<File | null>(null);
  const [result, setResult] = useState<string>('');
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const { showSnackBar } = useContext(CustomSnackBarContext);
  const compute = async (optionsValues: InitialValuesType, input: any) => {
    if (!input) return;

    setIsProcessing(true);

    try {
      const extractedText = await extractTextFromImage(input, optionsValues);
      setResult(extractedText);
    } catch (err: any) {
      showSnackBar(
        err.message || 'An error occurred while processing the image',
        'error'
      );
      setResult('');
    } finally {
      setIsProcessing(false);
    }
  };

  const getGroups: GetGroupsType<InitialValuesType> = ({
    values,
    updateField
  }) => [
    {
      title: 'OCR Options',
      component: (
        <Box>
          <SelectWithDesc
            selected={values.language}
            onChange={(val) => updateField('language', val)}
            description={
              'Select the primary language in the image for better accuracy'
            }
            options={getAvailableLanguages()}
          />
          <CheckboxWithDesc
            checked={values.detectParagraphs}
            onChange={(value) => updateField('detectParagraphs', value)}
            description={
              'Attempt to preserve paragraph structure in the extracted text'
            }
            title={'Detect Paragraphs'}
          />
        </Box>
      )
    }
  ];

  return (
    <ToolContent
      title={title}
      initialValues={initialValues}
      getGroups={getGroups}
      compute={compute}
      input={input}
      validationSchema={validationSchema}
      inputComponent={
        <ToolImageInput
          value={input}
          onChange={setInput}
          accept={['image/jpeg', 'image/png']}
          title={'Input Image'}
        />
      }
      resultComponent={
        <ToolTextResult
          title={'Extracted Text'}
          value={result}
          loading={isProcessing}
        />
      }
      toolInfo={{
        title: 'Image to Text (OCR)',
        description:
          'This tool extracts text from images using Optical Character Recognition (OCR). Upload an image containing text, select the primary language, and get the extracted text. For best results, use clear images with good contrast.'
      }}
    />
  );
}

import React, { useCallback, useState } from 'react';
import { Box } from '@mui/material';
